"""Generated site files: tag and stage indexes, Atom and JSON feeds, aliases and sitemap."""

import html
import json
import os
import posixpath
from datetime import UTC, date, datetime
from urllib.parse import quote, urljoin
from xml.etree import ElementTree

from garden.garden_state import notes, warn
from garden.links import note_icon_svg
from garden.notes import is_listed, is_public
from garden.parsing import escape_brackets, quote_path

ATOM_NS = 'http://www.w3.org/2005/Atom'


def listed_tag_slugs():
    """Tag slugs that actually have a heading on the generated by-tag page."""
    return {
        tag['slug'] for note in notes.values() if is_listed(note) for tag in note['tag_entries']
    }


def tag_index(src):
    """Markdown list of every listed note, grouped by tag."""
    from typing import Any

    by_tag: dict[str, dict[str, Any]] = {}
    for n_src, n in notes.items():
        if not is_listed(n):
            continue
        for tag in n['tag_entries']:
            by_tag.setdefault(tag['slug'], {'name': tag['name'], 'notes': []})['notes'].append(
                (n['title'], n_src)
            )
    if not by_tag:
        return '\n\n*no tagged notes yet. add `tags: [name]` to a note.*\n'
    out = ['\n\n']
    for slug in sorted(by_tag, key=lambda value: by_tag[value]['name'].lower()):
        tag = by_tag[slug]
        out.append('## %s { #tag-%s }\n\n' % (tag['name'], slug))
        for title, n_src in sorted(tag['notes'], key=lambda x: x[0].lower()):
            rel = quote_path(posixpath.relpath(n_src, posixpath.dirname(src) or '.'))
            label = note_icon_svg(notes[n_src].get('icon')) + escape_brackets(title)
            out.append('- [%s](%s)\n' % (label, rel))
        out.append('\n')
    return ''.join(out)


def stage_index(src, stage):
    """Card list of every listed note in one growth stage."""
    items = sorted(
        (
            (n['title'], s, n['excerpt'], n.get('icon'))
            for s, n in notes.items()
            if n['stage'] == stage and is_listed(n)
        ),
        key=lambda x: x[0].lower(),
    )
    if not items:
        return '\n\n*nothing planted here yet.*\n'
    rel_dir = posixpath.dirname(src) or '.'
    count = '%d %s' % (len(items), 'note' if len(items) == 1 else 'notes')
    out = ['\n\n', '<p class="stage-count">%s</p>\n\n' % count, '<div class="stage-cards">\n']
    for title, s, excerpt, icon in items:
        rel = quote_path(posixpath.relpath(s, rel_dir))
        card = (
            '<a class="stage-card stage-%s" href="%s">%s'
            '<span class="stage-card-title">%s</span>'
            % (stage, rel, note_icon_svg(icon), html.escape(title))
        )
        if excerpt:
            card += '<span class="stage-card-excerpt">%s</span>' % html.escape(excerpt)
        card += '</a>\n'
        out.append(card)
    out.append('</div>\n\n')
    return ''.join(out)


def feed_timestamp(value):
    if isinstance(value, datetime):
        return value.isoformat() + ('Z' if value.tzinfo is None else '')
    if isinstance(value, date):
        return value.isoformat() + 'T00:00:00Z'
    try:
        return date.fromisoformat(str(value)[:10]).isoformat() + 'T00:00:00Z'
    except ValueError:
        return datetime.now(UTC).replace(microsecond=0).isoformat().replace('+00:00', 'Z')


def _feed_entries():
    return sorted(
        ((n['tended'], n) for n in notes.values() if is_listed(n)),
        key=lambda item: str(item[0]),
        reverse=True,
    )


def _feed_author(config):
    name = config.get('site_author') or config['site_name']
    author = {'name': name}
    if config.get('site_author_url'):
        author['url'] = config['site_author_url']
    return author


def write_feed(config, site_dir):
    ElementTree.register_namespace('', ATOM_NS)
    root = ElementTree.Element(
        '{%s}feed' % ATOM_NS, {'{http://www.w3.org/XML/1998/namespace}lang': 'en'}
    )
    site_url = config['site_url'].rstrip('/') + '/'
    ElementTree.SubElement(root, '{%s}title' % ATOM_NS).text = config['site_name']
    ElementTree.SubElement(root, '{%s}id' % ATOM_NS).text = config['site_url']
    ElementTree.SubElement(root, '{%s}link' % ATOM_NS, {'href': config['site_url']})
    ElementTree.SubElement(
        root,
        '{%s}link' % ATOM_NS,
        {'rel': 'self', 'href': urljoin(site_url, 'feed.xml'), 'type': 'application/atom+xml'},
    )
    generator = ElementTree.SubElement(root, '{%s}generator' % ATOM_NS)
    generator.text = 'digital-garden'
    author = ElementTree.SubElement(root, '{%s}author' % ATOM_NS)
    ElementTree.SubElement(author, '{%s}name' % ATOM_NS).text = _feed_author(config)['name']
    if config.get('site_author_url'):
        ElementTree.SubElement(author, '{%s}uri' % ATOM_NS).text = config['site_author_url']
    entries = _feed_entries()
    updated = (
        max((value for value, _ in entries), key=lambda value: str(value))
        if entries
        else date.today()
    )
    ElementTree.SubElement(root, '{%s}updated' % ATOM_NS).text = feed_timestamp(updated)
    for _, note in entries:
        url = urljoin(site_url, quote(note['url'], safe='/'))
        entry = ElementTree.SubElement(root, '{%s}entry' % ATOM_NS)
        ElementTree.SubElement(entry, '{%s}title' % ATOM_NS).text = note['title']
        ElementTree.SubElement(entry, '{%s}id' % ATOM_NS).text = url
        ElementTree.SubElement(entry, '{%s}link' % ATOM_NS, {'href': url})
        ElementTree.SubElement(entry, '{%s}updated' % ATOM_NS).text = feed_timestamp(note['tended'])
        ElementTree.SubElement(entry, '{%s}summary' % ATOM_NS, {'type': 'text'}).text = note[
            'excerpt'
        ]
    xml = ElementTree.tostring(root, encoding='utf-8', xml_declaration=True)
    head, sep, body = xml.partition(b'?>')
    # point browsers at the readable stylesheet so the feed isn't a raw wall of XML
    xml = head + sep + b'\n<?xml-stylesheet type="text/xsl" href="feed.xsl"?>' + body
    with open(os.path.join(site_dir, 'feed.xml'), 'wb') as f:
        f.write(xml)


def write_json_feed(config, site_dir):
    """JSON Feed 1.1, a machine-friendly companion to the Atom feed."""
    site_url = config['site_url'].rstrip('/') + '/'
    items = []
    for _, note in _feed_entries():
        url = urljoin(site_url, quote(note['url'], safe='/'))
        items.append(
            {
                'id': url,
                'url': url,
                'title': note['title'],
                'summary': note['excerpt'],
                'date_modified': feed_timestamp(note['tended']),
            }
        )
    feed = {
        'version': 'https://jsonfeed.org/version/1.1',
        'title': config['site_name'],
        'home_page_url': site_url,
        'feed_url': urljoin(site_url, 'feed.json'),
        'authors': [_feed_author(config)],
        'items': items,
    }
    with open(os.path.join(site_dir, 'feed.json'), 'w', encoding='utf-8') as f:
        json.dump(feed, f, ensure_ascii=False, indent=2)
        f.write('\n')


def write_aliases(config, site_dir):
    """Write a redirect page for every alias of a rendered note.

    Unlisted notes keep their aliases (the page still exists, it is only left
    out of indexes); drafts never get one.
    """
    base_url = config['site_url'].rstrip('/') + '/'
    for note in notes.values():
        if note.get('draft'):
            continue
        destination = urljoin(base_url, quote(note['url'], safe='/'))
        for alias in note.get('aliases', []):
            path = alias.strip().replace('\\', '/').strip('/')
            normalized = posixpath.normpath(path)
            if (
                not path
                or ':' in path
                or normalized.startswith('/')
                or any(part in {'.', '..'} for part in path.split('/'))
            ):
                warn('ignoring unsafe alias %r for %s' % (alias, note['title']))
                continue
            relative = (
                normalized + '/index.html' if not normalized.endswith('.html') else normalized
            )
            output = os.path.join(site_dir, *relative.split('/'))
            if os.path.exists(output):
                warn('alias %r for %s conflicts with an existing page' % (alias, note['title']))
                continue
            os.makedirs(os.path.dirname(output), exist_ok=True)
            safe_destination = html.escape(destination, quote=True)
            title = html.escape(note['title'])
            page = (
                '<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n'
                '<meta name="robots" content="noindex">\n'
                '<meta http-equiv="refresh" content="0; url=%s">\n'
                '<link rel="canonical" href="%s">\n'
                '<title>moved: %s</title>\n</head>\n<body>\n'
                '<p>this note moved to <a href="%s">%s</a>.</p>\n</body>\n</html>\n'
            ) % (safe_destination, safe_destination, title, safe_destination, title)
            with open(output, 'w', encoding='utf-8') as stream:
                stream.write(page)


def write_sitemap(config, site_dir):
    base = config['site_url'].rstrip('/') + '/'
    urls = [(base + 'graph.html', '')]
    for n in notes.values():
        if is_public(n):
            urls.append((urljoin(base, quote(n['url'], safe='/')), str(n['tended'])[:10]))
    lines = [
        '<?xml version="1.0" encoding="UTF-8"?>',
        '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">',
    ]
    for loc, mod in urls:
        lines.append(
            '<url><loc>%s</loc>%s</url>'
            % (html.escape(loc), '<lastmod>%s</lastmod>' % mod if mod else '')
        )
    lines.append('</urlset>')
    with open(os.path.join(site_dir, 'sitemap.xml'), 'w', encoding='utf-8') as fh:
        fh.write('\n'.join(lines))


def write_site_files(config):
    """config needs site_url, site_name and site_dir."""
    site_dir = config['site_dir']
    write_feed(config, site_dir)
    write_json_feed(config, site_dir)
    write_aliases(config, site_dir)
    write_sitemap(config, site_dir)
    sitemap = urljoin(config['site_url'].rstrip('/') + '/', 'sitemap.xml')
    with open(os.path.join(site_dir, 'robots.txt'), 'w', encoding='utf-8') as fh:
        fh.write('User-agent: *\nAllow: /\nSitemap: %s\n' % sitemap)
